REVOKE INSERT ON public.review_events FROM authenticated;
DROP POLICY "Own case events create" ON public.review_events;
CREATE OR REPLACE FUNCTION public.record_review_case_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF TG_OP = 'INSERT' THEN INSERT INTO public.review_events (case_id,user_id,action,detail) VALUES (NEW.id,NEW.user_id,'created','Case opened'); ELSIF ROW(OLD.title,OLD.assignee,OLD.status,OLD.questions,OLD.evidence_notes) IS DISTINCT FROM ROW(NEW.title,NEW.assignee,NEW.status,NEW.questions,NEW.evidence_notes) THEN INSERT INTO public.review_events (case_id,user_id,action,detail) VALUES (NEW.id,NEW.user_id,CASE WHEN NEW.status IS DISTINCT FROM OLD.status THEN NEW.status ELSE 'updated' END,CASE WHEN NEW.status IS DISTINCT FROM OLD.status THEN 'Status: ' || OLD.status || ' → ' || NEW.status ELSE 'Review details updated' END); END IF; RETURN NEW; END $$;
CREATE TRIGGER record_review_case_event_after_write AFTER INSERT OR UPDATE ON public.review_cases FOR EACH ROW EXECUTE FUNCTION public.record_review_case_event();